import {VERSION,DAY,SKILLS,skillById,questionPool,initialData,newProfile,validateImport,profileSummary,skillStats,factSecure,explain,columnSteps,localDay,uid} from './engine.mjs';
import {DOMAINS,syllabusIds,domainFor,answerMatches,validDrawing,parseNumber} from './curriculum.mjs';
import {initLearning,competency,planSummary,nextAdaptive,recordLearning,probeIds} from './adaptive.mjs';
import {esc,icon,kit,stadium,diagram,mathText} from './visuals.mjs';
import {earnedXP,eligibleRecord,newPersonalBest} from './rewards.mjs';
import {goalsMarkup,pathMarkup,factMapMarkup,workedMarkup,penaltyArena} from './experience.mjs';
import {warmupProgress,clockDelta,academyPath} from './progression.mjs';

const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const STORAGE='numbergrove.data.v1',DRAFT='numbergrove.round.v1';
const app=$('#app'),modalRoot=$('#modal-root');
let data,storageWarning='',session=null,result=null,view='home',year=3,domain='all',search='',tableView=3,pendingSkill=null,tickId=null,advanceId=null,lastTick=0,lastSave=0,returnFocus=null,pendingImport=null,audio;
try{const raw=localStorage.getItem(STORAGE);data=raw?validateImport(JSON.parse(raw)):initialData();}catch{data=initialData();storageWarning='Progress could not be loaded. Restore a backup in Coach.';}
for(const p of data.profiles){const placeholders={'Pupil 1':['Ace',3],'Pupil 2':['Carter',3],'Pupil 3':['Cruz',5]};const renamed=placeholders[p.name];if(renamed){p.name=renamed[0];p.year=renamed[1];}initLearning(p);}
const routeMap={today:'home',skills:'syllabus',tables:'syllabus',progress:'stats',grownups:'coach'};
let initialRoute=location.hash.slice(1);view=routeMap[initialRoute]||(['home','syllabus','stats','coach','players'].includes(initialRoute)?initialRoute:'home');
try{const s=JSON.parse(localStorage.getItem(DRAFT)||'null');if(['football-v2','football-v3'].includes(s?.schema)&&data.profiles.some(p=>p.id===s.profileId)&&Number.isFinite(s.elapsed)&&s.q&&s.skillIds.every(skillById)){session=s;session.paused=true;session.pausedEver=true;data.activeId=s.profileId;}}catch{}
const player=()=>data.profiles.find(p=>p.id===(session?.profileId||data.activeId))||data.profiles[0];
const colours=['#326443','#4c70be','#c0874e','#7179a8'];
const playerIndex=p=>Math.max(0,data.profiles.findIndex(x=>x.id===p.id));
const shirtNumber=p=>[9,7,10,11][playerIndex(p)%4];
const clubPoints=p=>p.pointsTotal??p.sessions.reduce((n,s)=>n+s.points,0);
const level=p=>1+Math.floor(clubPoints(p)/200);
const totalGoals=p=>p.goalsTotal??p.sessions.reduce((n,s)=>n+s.correct,0);
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(data));return true;}catch{storageWarning='This browser cannot save progress. Download a backup in Coach.';return false;}}
function saveRound(){try{if(session)localStorage.setItem(DRAFT,JSON.stringify(session));else localStorage.removeItem(DRAFT);}catch{storageWarning='This round cannot be saved in this browser.';}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3300);}
function profileDot(p){return `<span class="profile-dot ${p.name.toLowerCase()==='ace'?'ace':p.name.toLowerCase()==='cruz'?'cruz':''}">${shirtNumber(p)}</span>`;}
function brand(){return `<a class="brand" href="#home" data-action="home" aria-label="Matchday Maths home"><span class="brand-mark">${icon('ball',28)}</span><span class="brand-type">MATCHDAY MATHS<small>THE NUMBER ACADEMY</small></span></a>`;}
function header(){const p=player();return `<header class="header">${brand()}${data.activeId&&view!=='players'?`<nav class="header-nav" aria-label="Main navigation">${[['home','Play','ball'],['syllabus','Syllabus','grid'],['stats','Trophies','trophy']].map(([id,label,symbol])=>`<button class="nav-btn ${view===id?'active':''}" data-action="nav" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(symbol,19)}${label}</button>`).join('')}</nav>`:''}<div class="header-tools"><button class="icon-btn sound-header" data-action="sound" aria-label="Sound ${data.settings.sound?'on':'off'}" aria-pressed="${data.settings.sound}">${icon(data.settings.sound?'sound':'mute',18)}</button>${data.activeId?`<button class="profile-mini" data-action="players" aria-label="Switch player">${profileDot(p)}${esc(p.name)}</button>`:''}<button class="icon-btn" data-action="nav" data-view="coach" aria-label="Coach and settings">${icon('coach',19)}</button></div></header>`;}
function footer(){return `<footer class="footer"><span>${icon('shield',13)} Progress stays on this device.</span><button class="text-btn" data-action="nav" data-view="coach">Coach’s corner ${icon('arrow',12)}</button></footer>`;}
function navigate(next){if(session){pause();return;}closeDialog();result=null;view=next;location.hash=next;render();scrollTo({top:0});}
window.addEventListener('hashchange',()=>{if(!session&&!result){view=routeMap[location.hash.slice(1)]||(['home','syllabus','stats','coach','players'].includes(location.hash.slice(1))?location.hash.slice(1):'home');render();}});
function render(){document.body.classList.toggle('reduce-motion',!!data.settings.reduceMotion);if(session){renderGame();return;}if(result){renderResult();return;}const content=!data.activeId&&!['coach','syllabus'].includes(view)?'players':view;app.innerHTML=`<div class="shell">${header()}<main id="main" class="${content==='players'?'welcome':'page'}" tabindex="-1">${storageWarning?`<div class="storage-warning" role="alert">${esc(storageWarning)}</div>`:''}${({players:playersPage,home:homePage,syllabus:syllabusPage,stats:statsPage,coach:coachPage}[content]||homePage)()}</main>${footer()}</div>`;}
function playersPage(){return `<section class="welcome-hero"><div class="eyebrow">${icon('shield',14)} THE NUMBER ACADEMY</div><h1>YOUR CLUB.<br><em>YOUR NEXT GOAL.</em></h1><p>Pick your player. Kick off.</p><div class="hero-art">${stadium()}</div><div class="floating-pill">${icon('ball',15)} SMALL SHOTS. BIG WINS.</div><span class="hero-edition">NUMBER SKILLS / BIG AMBITIONS</span></section><div class="intro-row"><div><h2>Choose your player</h2></div><button class="text-btn" data-action="new-player">${icon('plus',14)} New player</button></div><div class="players">${data.profiles.map((p,i)=>{const best=Math.max(0,...Object.values(p.records||{}).map(r=>r.points));return `<button class="player-card" data-action="choose-player" data-id="${p.id}" aria-label="Play as ${esc(p.name)}, Year ${p.year||'own pace'}"><div class="player-label">${icon('shield',12)} YEAR ${p.year||'OPEN'} SQUAD</div><h3>${esc(p.name)}</h3><div class="player-detail">LEVEL ${level(p)} <span>·</span> ${clubPoints(p)} XP</div><span class="jersey">${kit(shirtNumber(p),colours[i%4],115)}</span><div class="player-bottom"><span class="play-label">PLAY ${icon('arrow',17)}</span><span class="player-best">${icon('trophy',14)} ${best?`${best} XP`:'First kick'}</span></div></button>`;}).join('')}</div><div class="welcome-foot"><span>${icon('shield',14)} Your own progress. Saved here.</span><button class="text-btn" data-action="browse">Syllabus ${icon('arrow',14)}</button></div>`;}
function metric(value,label,symbol){return `<div class="metric"><span class="metric-icon">${icon(symbol,23)}</span><div><strong>${value}</strong><small>${label}</small></div></div>`;}
function shortTitle(s){if(s.id.startsWith('col'))return `${s.title} · ${s.digits} digits${!s.regroup?' · no exchange':''}`;return s.title;}
function symbolFor(s){if(s.table)return `×${s.table}`;if(['mix348','mixAll'].includes(s.id))return '×';if(s.kind==='div')return '÷';if(s.kind==='place')return '123';if(s.kind==='coladd'||s.kind==='add')return '+';if(s.kind==='colsub'||s.kind==='sub')return '−';if(s.kind==='bonds')return s.id==='bonds10'?'10':'20';return DOMAINS.find(d=>d.id===domainFor(s))?.symbol||'?';}
function drillCard(id,clickable=true){const s=skillById(id),c=data.activeId?competency(player(),id):{secure:false,n:0,coverage:0};return `<${clickable?'button':'div'} class="drill-card" ${clickable?`data-action="skill" data-skill="${id}" aria-label="Practise ${esc(shortTitle(s))}"`:''}><span class="drill-icon">${symbolFor(s)}</span><h3>${esc(shortTitle(s))}</h3><div class="drill-meta"><span class="status ${c.secure?'fit':c.n?'training':''}">${c.secure?'Match fit':c.n?'Training':'New'}</span>${clickable?icon('arrow',14):icon('whistle',14)}</div><div class="skill-bar"><i style="width:${c.secure?100:Math.min(90,c.coverage||0)}%"></i></div></${clickable?'button':'div'}>`;}
function homePage(){const p=player(),sum=profileSummary(p),plan=planSummary(p);return `<div class="heading"><div><div class="eyebrow" style="color:var(--muted);margin-bottom:8px">PLAYER ${shirtNumber(p)} / YEAR ${p.year||'OPEN'}</div><h1>LET’S GO, ${esc(p.name)}.</h1></div><span class="small-tag">${icon('flame',14)} ${sum.streak} DAY STREAK</span></div><div class="hero-grid"><section class="play-hero"><div class="eyebrow">${icon('whistle',14)} YOUR NEXT SESSION IS READY</div><h1>TRAIN SMART.<br><em>SCORE BIG.</em></h1><button class="btn lime big" data-action="play">${p.placementComplete?'PLAY NOW':warmupProgress(p)?'PLAY ON':'KICK OFF'} ${icon('arrow',19)}</button><div class="hero-meta"><span>${icon('clock',13)} ${p.placementComplete?'10 shots':`${12-warmupProgress(p)} warm-up shots`}</span><span>${icon('coach',13)} Picked for you</span></div><div class="hero-art">${stadium()}</div></section>${goalsMarkup(p)}</div><div class="metrics">${metric(sum.todayCorrect,'goals today','ball')}${metric(Math.max(0,...Object.values(p.records||{}).map(r=>r.points)),'personal best XP','trophy')}${metric(sum.factsSecure,'facts match fit','shield')}</div>${pathMarkup(p)}<div class="section-head"><div><h2>Coach’s next moves</h2></div><button class="text-btn" data-action="how">${icon('whistle',15)} Why these?</button></div><div class="focus-strip">${plan.map(x=>{const sk=skillById(x.id);return `<div class="focus-card"><span>${symbolFor(sk)}</span><div><small>${{foundation:'FIRST TOUCH',tables:'BALL CONTROL',written:'SET PIECES',curriculum:'THE WIDER GAME'}[x.lane]}</small><b>${esc(shortTitle(sk))}</b></div>${icon('whistle',15)}</div>`;}).join('')}</div><div class="home-bottom"><div><b>LEVEL ${level(p)}</b><span>${clubPoints(p)%200}/200 XP</span></div><div class="xp"><i style="width:${clubPoints(p)%200/2}%"></i></div><button class="text-btn" data-action="nav" data-view="syllabus">Explore the syllabus ${icon('arrow',14)}</button></div>`;}
function syllabusBank(){const ids=syllabusIds(year).filter(id=>shortTitle(skillById(id)).toLowerCase().includes(search.toLowerCase()));return DOMAINS.filter(d=>domain==='all'||domain===d.id).map((d,i)=>{const list=ids.filter(id=>domainFor(skillById(id))===d.id);return list.length?`<section class="domain-section"><div class="domain-title"><span class="domain-number">${i+1}</span><h2>${d.title}</h2><small>${list.length} drills</small></div><div class="drill-grid">${list.map(id=>drillCard(id)).join('')}</div></section>`:'';}).join('')||'<div class="empty"><h3>No drills found.</h3><p>Try “table”, “time” or “fraction”.</p></div>';}
function syllabusPage(){return `<div class="heading"><div><div class="eyebrow" style="color:var(--muted);margin-bottom:7px">THE TRAINING BOOK</div><h1>THE SYLLABUS.</h1></div><div class="year-toggle" role="group" aria-label="Syllabus year"><button class="${year===3?'active':''}" data-action="year" data-year="3" aria-pressed="${year===3}">Year 3</button><button class="${year===5?'active':''}" data-action="year" data-year="5" aria-pressed="${year===5}">Year 5</button></div></div><div class="syllabus-tools"><input id="skill-search" class="search" type="search" aria-label="Find a drill" placeholder="Find a drill…" value="${esc(search)}"><span class="muted">Pick a drill. Start playing.</span></div><div class="filters" role="group" aria-label="Maths topic"><button class="filter ${domain==='all'?'active':''}" data-action="domain" data-domain="all">All</button>${DOMAINS.map(d=>`<button class="filter ${domain===d.id?'active':''}" data-action="domain" data-domain="${d.id}">${d.title}</button>`).join('')}</div><div id="syllabus-bank">${syllabusBank()}</div>`;}
const eligible=eligibleRecord;
function recordKey(s){return s.recordKey||`${[...s.skillIds].sort().join(',')}|${s.duration}`;}
function bestFor(key,p=player()){return p.records?.[key]||null;}
function recordLabel(s){return s.manual?shortTitle(skillById(s.manual)):['football-v2','football-v3'].includes(s.schema)?`Coach training · League ${s.league||1}`:s.skillIds.length===1?skillById(s.skillIds[0]).title:'Mixed practice';}
function recordsMarkup(p){const records=Object.values(p.records||{}).sort((a,b)=>b.endedAt-a.endedAt);return records.length?`<div class="records">${records.slice(0,10).map(s=>`<div class="record">${icon('trophy',22)}<div><b>${esc(recordLabel(s))}</b><small>${s.correct}/${s.attempts} goals · ${Math.round(s.elapsed)}s</small></div><strong>${s.points}</strong></div>`).join('')}</div>`:'<div class="empty">'+icon('trophy',33)+'<h3>Your first record is waiting.</h3><button class="btn soft" data-action="play" style="margin-top:17px">Kick off '+icon('arrow',15)+'</button></div>';}
function medals(p){const s=profileSummary(p),ss=p.sessions,goals=totalGoals(p);return [['First kick','Finish a match','ball',ss.some(x=>x.complete)],['Hat-trick','3 goals in a row','flame',ss.some(x=>x.bestStreak>=3)],['Clean sheet','10/10 without help','shield',ss.some(x=>x.attempts>=10&&x.correct===x.attempts&&!x.hintsUsed)],['Golden boot','50 goals','trophy',goals>=50],['Match regular','Train on 3 days','clock',s.days.length>=3],['Record breaker','Set a personal best','star',Object.keys(p.records||{}).length>0],['Midfield master','Practise 3, 4 and 8','ball',[3,4,8].every(t=>p.learning[`table${t}`]?.correct>=5)],['Match fit','12 secure facts','shield',s.factsSecure>=12]];}
function statsPage(){const p=player(),s=profileSummary(p);return `<div class="heading"><div><div class="eyebrow" style="color:var(--muted);margin-bottom:7px">${esc(p.name.toUpperCase())}’S CLUBHOUSE</div><h1>THE TROPHY ROOM.</h1></div><span class="small-tag">${icon('star',14)} LEVEL ${level(p)}</span></div><div class="metrics">${metric(clubPoints(p),'total XP','star')}${metric(totalGoals(p),'goals scored','ball')}${metric(s.factsSecure,'facts match fit','shield')}</div>${pathMarkup(p)}<div id="table-tracker-host">${factMapMarkup(p,tableView)}</div><div class="two-col"><section class="panel"><h2 style="font-size:21px">Keep showing up.</h2><div class="week">${Array.from({length:7},(_,i)=>{const when=Date.now()-(6-i)*DAY,done=s.days.includes(localDay(when));return `<div class="day ${done?'done':''}">${new Date(when).toLocaleDateString('en-GB',{weekday:'short'})}<i>${done?icon('check',15):new Date(when).getDate()}</i></div>`;}).join('')}</div><div class="level-line"><strong>LEVEL ${level(p)}</strong><span>${clubPoints(p)%200}/200 XP</span></div><div class="xp"><i style="width:${clubPoints(p)%200/2}%"></i></div></section><section class="panel"><h2 style="font-size:21px">Your personal bests</h2>${recordsMarkup(p)}</section></div><section class="panel" style="margin-top:21px"><h2 style="font-size:21px">Your medals</h2><div class="badge-grid">${medals(p).map(([name,detail,sym,won])=>`<div class="badge ${won?'':'locked'}" aria-label="${won?'Won':'Not won'}: ${name}. ${detail}"><span class="badge-icon">${icon(sym,24)}</span><b>${name}</b><small>${detail}</small></div>`).join('')}</div></section><section class="panel" style="margin-top:21px"><div class="section-head" style="margin-top:0"><h2>Recent matches</h2><button class="text-btn" data-action="export-csv">Export ${icon('download',14)}</button></div>${historyMarkup(p)}</section>`;}
function historyMarkup(p){return p.sessions.length?`<div class="report-wrap"><table class="report"><thead><tr><th>Date</th><th>Match</th><th>Goals</th><th>XP</th><th>Time</th></tr></thead><tbody>${[...p.sessions].reverse().slice(0,20).map(s=>`<tr><td>${new Date(s.endedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</td><td>${esc(s.mode==='check'?'Warm-up':recordLabel(s))}<small>${s.complete?'Full match':'Saved early'}${s.hintsUsed?' · Coach helped':''}${s.pausedEver?' · paused':''}</small></td><td>${s.correct}/${s.attempts}</td><td>${s.points}</td><td>${Math.round(s.elapsed)}s</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>A fresh start.</h3><p>Your match results appear here.</p></div>';}
function coachPage(){const p=player();return `<div class="heading"><div><div class="eyebrow" style="color:var(--muted);margin-bottom:7px">FOR GROWN-UPS</div><h1>COACH’S CORNER.</h1></div></div><div class="coach-grid"><section class="panel"><div class="section-head" style="margin-top:0"><h2>The squad</h2><button class="text-btn" data-action="new-player">Add ${icon('plus',14)}</button></div>${data.profiles.map(x=>`<div class="profile-row">${profileDot(x)}<div><strong>${esc(x.name)}</strong><small>Year ${x.year||'open'} · ${x.sessions.length} matches</small></div><button class="text-btn" data-action="report" data-id="${x.id}">Report</button><button class="text-btn" data-action="edit-player" data-id="${x.id}">Edit</button></div>`).join('')}<div class="coach-note">Profiles are local to this browser, without passwords. Anyone on this computer can switch players. Names and results are not sent to a server by the app.</div></section><section class="panel"><h2 style="font-size:21px">Backups & settings</h2><div class="data-buttons"><button class="btn white" data-action="backup">${icon('download',15)} Backup</button><button class="btn white" data-action="import">Restore backup</button></div><input type="file" id="import-file" accept=".json,application/json" hidden><div class="coach-note">Clearing browser data removes local progress. A backup moves the whole squad to another browser or computer.</div><label style="display:flex;align-items:center;gap:9px;font-size:12px;margin-top:19px"><input id="reduce-motion" type="checkbox" ${data.settings.reduceMotion?'checked':''}> Reduce motion</label><button class="text-btn" data-action="sound" style="margin-top:13px">${icon(data.settings.sound?'sound':'mute',16)} Sound ${data.settings.sound?'on':'off'}</button></section></div><section class="panel coach-copy"><h2 style="font-size:21px;color:var(--ink)">How the practice engine decides</h2><ol><li><strong>Starting point:</strong> a 12-question warm-up checks number facts, tables and written methods. It is a sample, not a mastery verdict.</li><li><strong>Prerequisites:</strong> the engine selects supporting skills from a dependency graph. For example, crossing 10 depends on bonds to 10. Repeated difficulties trigger a simpler supporting question.</li><li><strong>Balanced training:</strong> early sessions concentrate on foundations and tables, with written methods and a small wider-curriculum sample. Secure prerequisites allow more curriculum practice.</li><li><strong>Retrieval:</strong> mistakes return after other questions. Familiar facts return after increasing gaps of 1, 3, 7, 14, 30 and 60 days. Hints reset the recall interval.</li><li><strong>Progression and mastery differ:</strong> recent independent accuracy can make a pupil ready for the next skill. “Match fit” needs spaced evidence, coverage and repeated independent success. Same-day repetition cannot manufacture mastery.</li></ol><div class="coach-note">These are transparent product rules. They do not guarantee permanent memory or diagnose a learning need. Response time includes reading and typing. The syllabus page remains available for teacher-directed practice.</div></section><section class="panel coach-copy" style="margin-top:21px"><h2 style="font-size:21px;color:var(--ink)">Curriculum scope</h2><p>The syllabus organises practice around England’s Year 3 and Year 5 mathematical domains, with earlier prerequisites accessible for both. Year 3 emphasises the 3, 4 and 8 tables; Year 5 consolidates all tables to 12. Wales uses progression steps, so year labels here describe the England map.</p><p>There are ${SKILLS.length} exercise families, including visual and construction tasks. A finite question bank cannot include every possible question or replace discussion, practical measuring, physical 3D model-making and teacher assessment. A fuller objective map is included with the source.</p><div class="sources"><a href="https://www.gov.uk/government/publications/national-curriculum-in-england-mathematics-programmes-of-study/national-curriculum-in-england-mathematics-programmes-of-study" target="_blank" rel="noopener">England curriculum ↗</a><a href="https://hwb.gov.wales/curriculum-for-wales/areas-of-learning-and-experience/mathematics-and-numeracy/descriptions-of-learning/" target="_blank" rel="noopener">Curriculum for Wales ↗</a><a href="https://www.ncetm.org.uk/features/the-five-big-ideas-at-primary-fluency/" target="_blank" rel="noopener">NCETM fluency ↗</a></div></section><section class="panel coach-copy" style="margin-top:21px"><h2 style="font-size:21px;color:var(--ink)">Records and rewards</h2><p>An independent correct answer earns 10 XP plus a streak bonus of up to 10. Supported correct answers earn 2 XP. Stars reflect accuracy. Timed records require a full match without hints or pauses; warm-ups do not set records. Individual-drill records compare the same drill and time limit. Adaptive-training records are grouped by year and training league because the question mix changes with learning.</p><p>The clock counts answer time. Feedback gives time to learn. Auto training has a 1, 2 or 3 minute clock, set per player. New timing records are kept separate from earlier versions. Detailed history retains the most recent 500 matches. Personal records, lifetime XP and recall evidence are kept separately.</p></section>`;}

function startMatch(manual=null){
 const p=player();data.activeId=p.id;save();closeDialog();result=null;
 const placement=!manual&&!p.placementComplete,probeStart=placement?warmupProgress(p):0,league=Math.min(5,1+Math.floor(SKILLS.filter(s=>competency(p,s.id).ready).length/12));
 const s=manual?skillById(manual):null,duration=placement?180:manual?(s.category==='columns'||s.id==='mul5'||s.id==='division5'?180:s.extra?180:60):([60,120,180].includes(p.trainingSeconds)?p.trainingSeconds:120);
 session={schema:'football-v3',id:uid(),profileId:p.id,skillIds:[],manual,league,placement,probeIndex:probeStart,mode:placement?'check':'timed',duration,target:placement?12-probeStart:10,recordKey:manual?`v3:drill:${manual}:${duration}`:`v3:training:y${p.year}:league${league}:${duration}`,startedAt:Date.now(),elapsed:0,currentMs:0,attempts:0,correct:0,points:0,streak:0,bestStreak:0,rows:[],seen:[],retries:[],paused:false,pausedEver:false,hintsUsed:0,assisted:false,phase:'question',q:null,selection:null,answer:'',digits:[],notes:[],drawing:[],bars:[],angle:30};
 nextQuestion(false);renderGame();startTick();saveRound();scrollTo({top:0});
}
function nextQuestion(renderHost=true){
 clearTimeout(advanceId);if(!session)return;
 if(session.attempts>=session.target){finishMatch(true);return;}
 const next=nextAdaptive(player(),session);if(!next?.q)throw Error('No next exercise');
 if(next.retryKey){const i=session.retries.findIndex(r=>r.q.key===next.retryKey);if(i>=0)session.retries.splice(i,1);}
 if(next.advanceProbe)session.probeIndex++;
 session.q=next.q;session.selection=next;session.assisted=false;session.phase='question';session.answer='';session.digits=[];session.notes=[];session.drawing=[];session.bars=[];session.angle=30;session.currentMs=0;session.lastDigit=null;
 session.seen.push(session.q.key);if(!session.skillIds.includes(session.q.skillId))session.skillIds.push(session.q.skillId);saveRound();
 if(renderHost&&$('#question-host')){renderQuestion();updateLive();}
}
const clock=s=>`${Math.floor(Math.max(0,Math.ceil(s))/60)}:${String(Math.max(0,Math.ceil(s))%60).padStart(2,'0')}`;
function shotTrack(){return `${Array.from({length:session.target},(_,i)=>`<i class="${session.rows[i]?(session.rows[i].correct?'goal':'miss'):i===session.attempts?'active':''}" aria-hidden="true"></i>`).join('')}<span class="shot-count">${Math.min(session.target,session.attempts+(session.phase==='question'?1:0))}/${session.target}</span>`;}
function renderGame(){const p=player(),best=bestFor(session.recordKey);app.innerHTML=`<div class="game-shell"><header class="game-header">${brand()}<div class="game-header-right"><span class="profile-mini">${profileDot(p)}${esc(p.name)}</span><button class="icon-btn" data-action="pause" aria-label="Pause match">${icon('pause',17)}</button></div></header><main id="main" class="game-main"><div class="game-title"><div><div class="eyebrow">${session.placement?'WARM-UP':session.manual?'SYLLABUS DRILL':'COACH-LED TRAINING'}</div><h1>${session.manual?esc(shortTitle(skillById(session.manual))):session.placement?'LET’S PLAY.':'YOUR NEXT SHOT.'}</h1></div><div class="game-metrics"><div class="game-metric"><strong id="live-goals">${session.correct}</strong><small>Goals</small></div><div class="game-metric"><strong id="live-streak">${session.streak}</strong><small>Streak</small></div><div class="game-metric" id="timer-box"><strong id="live-time">${clock(session.duration-session.elapsed)}</strong><small id="timer-caption">Time</small></div></div></div><div class="shot-track" id="shot-track" aria-label="Match progress">${shotTrack()}</div><div class="game-grid"><section id="question-host" class="question-card" aria-label="Maths question"></section><aside class="game-side"><section class="pitch-card"><div class="match-card-top"><span>${icon('ball',12)} LIVE TRAINING</span><i></i></div>${penaltyArena()}<div class="pitch-score"><span>YOUR<br>SCORE</span><strong id="live-xp">${session.points}<small> XP</small></strong></div><div class="pitch-best"><span>${session.placement?'WARM-UP':'PERSONAL BEST'}</span><b>${session.placement?'FIND YOUR LEVEL':best?best.points+' XP':'SET YOUR FIRST'}</b></div></section><div id="keypad"><div class="numpad" role="group" aria-label="Number keypad">${[1,2,3,4,5,6,7,8,9].map(n=>`<button data-action="key" data-key="${n}" aria-label="${n}">${n}</button>`).join('')}<button class="key-muted" data-action="key" data-key="clear" aria-label="Clear answer">C</button><button data-action="key" data-key="0">0</button><button class="key-muted" data-action="key" data-key="back" aria-label="Delete last digit">${icon('erase',18)}</button></div><div class="symbol-keys" id="symbol-keys">${['.','/','−',',',' '].map(k=>`<button data-action="key" data-key="${k}" aria-label="${k===' '?'Space':k==='/'?'Fraction bar':k===','?'Comma':k==='−'?'Minus':'Decimal point'}">${k===' '?'␣':k}</button>`).join('')}</div></div><div class="side-finish"><button class="text-btn" data-action="finish">Save & finish ${icon('arrow',12)}</button></div></aside></div></main></div>`;renderQuestion();if(session.paused)showPauseOverlay();}
function coreExpression(q,reveal=false){const a=q.a?.toLocaleString('en-GB'),b=q.b?.toLocaleString('en-GB'),ans=String(q.answer);switch(q.op){case 'bond':return `${a} + ${reveal?ans:'□'} = ${q.total}`;case 'missing+':return `${reveal?ans:'□'} + ${b} = ${q.total}`;case 'missing−':return `${a} − ${reveal?ans:'□'} = ${q.total}`;case 'double':return `Double ${a}${reveal?' = '+ans:''}`;case 'half':return `Half of ${a}${reveal?' = '+ans:''}`;case 'place':return String(q.a).split('').map((digit,i,str)=>({digit,i})).map(({digit,i})=>i===String(q.a).length-1-Math.log10(q.power)?`<span class="highlight">${digit}</span>`:digit).join('');default:return `${a} <span class="op">${q.op}</span> ${b}${reveal?' = '+ans:' <span class="op">=</span>'}`;}}
function equationLabel(q,reveal=true){if(q.expression!==undefined)return q.expression||skillById(q.skillId).title;return coreExpression(q,reveal).replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim();}
function questionPrompt(q){if(q.prompt!==undefined)return q.prompt;return q.op==='place'?'Value of the green digit?':q.op==='bond'?`Make ${q.total}`:q.op?.startsWith('missing')?'Find the gap':q.key.startsWith('column')?'Start with the ones.':q.op==='double'||q.op==='half'?'':q.op==='×'?'Multiply':q.op==='÷'?'Divide':q.op==='+'?'Add':'Subtract';}
function columnMarkup(q,done=false){const n=Math.max(String(q.a).length,String(q.b).length,String(q.answer).length),labels=['O','T','H','Th','TTh','HTh'],a=String(q.a).padStart(n,' ').split(''),b=String(q.b).padStart(n,' ').split(''),correct=String(q.answer).padStart(n,'0');return `<div class="column-layout" style="--digits:${n}"><span></span>${Array.from({length:n},(_,i)=>`<span class="head">${labels[n-i-1]}</span>`).join('')}<span></span>${Array.from({length:n},(_,i)=>`<input class="column-note" aria-label="Optional note for ${labels[n-i-1]} column" inputmode="numeric" maxlength="2" data-note="${i}" value="${esc(session.notes[i]||'')}" ${done?'disabled':''}>`).join('')}<span></span>${a.map(x=>`<span>${x.trim()||'&nbsp;'}</span>`).join('')}<span>${q.op}</span>${b.map(x=>`<span>${x.trim()||'&nbsp;'}</span>`).join('')}<span class="under"></span>${Array.from({length:n},(_,i)=>`<span class="under"><input class="column-digit ${done?(Number(session.digits[i]||0)===Number(correct[i])?'correct':'incorrect'):''}" id="digit-${i}" data-digit="${i}" aria-label="Answer ${labels[n-i-1]} column" inputmode="numeric" maxlength="1" autocomplete="off" value="${esc(session.digits[i]||'')}" ${done?'disabled':''}></span>`).join('')}</div>`;}
function drawingMarkup(v,done){const points=session.drawing||[],path=points.map(p=>`${24+p[0]*45},${20+p[1]*43}`).join(' ');return `<div class="drawing" id="drawing-board"><svg viewBox="0 0 290 260" aria-hidden="true">${Array.from({length:6},(_,i)=>`<path d="M${24+i*45} 20v215M24 ${20+i*43}h225" stroke="#dfe7d6" stroke-width="1"/>`).join('')}<polyline points="${path}${points.length===v.sides&&points.length?' '+(24+points[0][0]*45)+','+(20+points[0][1]*43):''}" fill="${points.length===v.sides?'#7193d026':'none'}" stroke="#4e78bd" stroke-width="3"/></svg>${Array.from({length:36},(_,i)=>{const x=i%6,y=Math.floor(i/6),selected=points.some(p=>p[0]===x&&p[1]===y);return `<button type="button" class="dot-btn ${selected?'selected':''}" style="left:${(24+x*45)/290*100}%;top:${(20+y*43)/260*100}%" data-action="draw-point" data-x="${x}" data-y="${y}" aria-label="Point ${x}, ${y}" aria-pressed="${selected}" ${done?'disabled':''}></button>`;}).join('')}</div>${!done?'<div class="drawing-actions"><button type="button" class="text-btn" data-action="draw-undo">Undo</button><button type="button" class="text-btn" data-action="draw-clear">Reset</button></div>':''}`;}
function basicHelpVisual(q){if(q.op==='×')return `<div class="math-array" style="grid-template-columns:repeat(${q.b},12px)">${Array.from({length:q.a*q.b},()=>'<i></i>').join('')}</div>`;if(['+','−','bond','double'].includes(q.op)&&q.a<=20){const total=Math.min(20,q.op==='+'||q.op==='double'?q.answer:q.op==='bond'?q.total:q.a),split=q.op==='+'||q.op==='bond'||q.op==='double'?q.a:q.answer;return `<div class="ten-frames">${Array.from({length:Math.max(1,Math.ceil(total/10))},(_,r)=>`<div class="ten-frame">${Array.from({length:10},(_,j)=>`<i class="${r*10+j<total?'filled':''} ${r*10+j>=split&&r*10+j<total?'second':''}"></i>`).join('')}</div>`).join('')}</div>`;}return '';}
function helpMarkup(q,small=false){const hints=q.hint||explain(q).steps,model=workedMarkup(q);return `<div class="help-box"><h3>${icon('whistle',15)} COACH’S REPLAY</h3>${model||(!q.hint?basicHelpVisual(q):'')}${model?`<details class="more-help"><summary>More help</summary>${hints.map(t=>`<div class="hint-step">${mathText(t)}</div>`).join('')}</details>`:hints.map(t=>`<div class="hint-step">${mathText(t)}</div>`).join('')}<button class="text-btn" data-action="hear-help">${icon('sound',14)} Hear it</button></div>`;}
function renderQuestion(){
 if(!session)return;const q=session.q,done=session.phase==='feedback',extra=skillById(q.skillId).extra,column=q.key.startsWith('column'),options=q.options;
 let content='',input='',isWords=false;
 if(extra){isWords=/[A-Za-z]/.test(q.expression||'');content=`<div class="q-prompt">${esc(questionPrompt(q))}</div>${q.expression?`<div class="q-equation ${isWords?'words':String(q.expression).length>19?'compact':''}">${mathText(q.expression)}</div>`:''}`;
 if(q.format==='drawing')content+=drawingMarkup(q.visual,done);else content+=diagram(q.visual,{angle:session.angle,points:session.drawing,bars:session.bars});
 }else{content=`<div class="q-prompt">${esc(questionPrompt(q))}</div>`;if(column)content+=columnMarkup(q,done);else content+=`<div class="q-equation ${['double','half'].includes(q.op)?'words':q.op==='place'?'compact':''}">${coreExpression(q)}</div>`;}
 if(options){const symbol=options.every(x=>['<','>','='].includes(String(x)));input=`<div class="choices ${options.some(x=>/[A-Za-z]/.test(x))?'words':''} ${symbol?'choice-symbols':''}" role="group" aria-label="Answer choices">${options.map(o=>`<button class="choice ${done?(answerMatches(q,o)?'correct':String(session.answer)===String(o)?'incorrect':''):''}" type="button" data-action="answer-choice" data-value="${esc(o)}" ${done?'disabled':''}>${mathText(o)}</button>`).join('')}</div>`;}
 else if(q.format==='angle')input=`<input type="range" min="0" max="180" step="1" class="angle-control" id="angle-control" aria-label="Turn the angle ray" value="${session.angle}" ${done?'disabled':''}>`;
 else if(q.format==='bars')input=`<div class="bar-answer-row">${q.visual.labels.map((l,i)=>`<label>${esc(l)}<span style="height:100px;width:60px;display:flex;align-items:flex-end;background:#f1f5e8;border-radius:5px;overflow:hidden"><i id="bar-view-${i}" style="display:block;background:${i?'#6489d2':'#7f9f55'};width:100%;height:${(session.bars[i]||0)*5}px"></i></span><input class="bar-input" type="number" min="0" max="20" inputmode="numeric" aria-label="${esc(l)} bar height" data-bar="${i}" value="${esc(session.bars[i]??'')}" ${done?'disabled':''}></label>`).join('')}</div>`;
 else if(q.format!=='drawing'&&!column)input=`<div class="answer-line">${q.unit==='£'?'<span class="unit">£</span>':''}<input class="answer-input ${q.format==='fraction'||q.format==='mixed'||q.format==='pair'||Number(q.answer)>9999?'wide':''} ${done?(session.rows.at(-1).correct?'correct':'incorrect'):''}" id="answer" aria-label="Your answer" inputmode="${['fraction','mixed','pair'].includes(q.format)?'text':q.format==='decimal'?'decimal':'numeric'}" autocomplete="off" maxlength="24" value="${esc(session.answer)}" placeholder="?" ${done?'disabled':''}>${q.unit&&q.unit!=='£'?`<span class="unit">${esc(q.unit)}</span>`:''}</div>`;
 let tail='';
 if(done){const last=session.rows.at(-1);tail=`<div class="feedback ${last.correct?'':'miss'}" role="status">${icon(last.correct?'ball':'whistle',30)}<div><h3>${last.correct?'GOAL!':'LET’S BUILD IT.'}</h3><p>${last.correct?`+${last.earned} XP${session.streak>=3?' · '+session.streak+' in a row':''}`:`${q.format==='drawing'?'Check the corners.':q.format==='bars'?'Match the bar heights.':q.format==='angle'?`Aim for ${q.answer}°.`:`Answer: ${Array.isArray(q.answer)?q.answer.join(', '):esc(q.answer)}`}`}</p></div><button class="btn ${last.correct?'soft':'white'}" data-action="next">Next ${icon('arrow',15)}</button></div>${!last.correct?helpMarkup(q):''}`;}
 else tail=`${!options?`<div class="shoot"><button class="btn big" type="submit">SHOOT ${icon('arrow',18)}</button></div><div class="enter-note">Enter ↵</div>`:''}<div id="answer-error" class="field-error" role="alert"></div><button class="coach-hint" type="button" data-action="hint">${icon('whistle',15)} Coach</button>${session.assisted?helpMarkup(q):''}`;
 $('#question-host').innerHTML=`<div class="q-toolbar"><span class="q-label ${session.selection.reason==='repair'?'replay':''}">${icon(session.selection.reason==='repair'?'reset':'ball',12)}${esc(session.selection.label)}</span><button class="voice-button" data-action="hear" aria-label="Read the question aloud">${icon('sound',17)}</button></div><form id="answer-form" novalidate>${content}${input}${tail}</form>`;
 $('#keypad').classList.toggle('hidden',!!options||['drawing','angle'].includes(q.format));$('#symbol-keys').classList.toggle('hidden',!q.format||q.format==='number'||q.format==='bars'||column);
 if(!done)requestAnimationFrame(()=>{if(column){const inputs=$$('.column-digit');session.lastDigit=inputs.length-1;inputs.at(-1)?.focus({preventScroll:true});}else $('#answer')?.focus({preventScroll:true});});
}
function submit(value=null){
 if(!session||session.paused||session.phase!=='question')return;
 const q=session.q,column=q.key.startsWith('column');
 if(value===null){if(column){session.digits=$$('.column-digit').map(x=>x.value);if(!session.digits.some(x=>x!==''))return answerError('Add your answer.');value=Number(session.digits.map(x=>x||'0').join(''));}else if(q.format==='drawing')value=validDrawing(session.drawing,q.visual.sides);else if(q.format==='angle')value=session.angle;else if(q.format==='bars'){session.bars=$$('.bar-input').map(x=>x.value);if(session.bars.some(x=>x===''))return answerError('Set both bars.');value=session.bars.map(Number);}else{session.answer=$('#answer')?.value.trim()||'';if(!session.answer)return answerError('Add your answer.');if(q.format!=='pair'&&!Number.isFinite(parseNumber(session.answer)))return answerError('Use a number.');value=session.answer;}}
 else session.answer=String(value);
 const correct=answerMatches(q,value),help=session.assisted;
 session.attempts++;session.correct+=correct?1:0;session.streak=correct&&!help?session.streak+1:0;session.bestStreak=Math.max(session.bestStreak,session.streak);
 const earned=earnedXP(correct,help,session.streak);session.points+=earned;
 const row={q:{...q},typed:value,correct,assisted:help,ms:Math.round(session.currentMs),earned,reason:session.selection.reason,detail:session.selection.detail};session.rows.push(row);
 recordLearning(player(),q,correct,help,row.ms,session.id,Date.now(),session.selection.reason==='probe');
 if(session.selection.reason==='probe'){player().placementProgress=session.probeIndex;if(session.probeIndex>=probeIds(player()).length)player().placementComplete=true;}
 if(!correct||help)session.retries.push({q:{...q},at:session.attempts+2});
 session.phase='feedback';save();saveRound();renderQuestion();updateLive();sound(correct);if(correct){$('#mini-ball').style.setProperty('--shot-x',[-64,62,-38,48][session.attempts%4]+'px');$('#mini-ball').classList.add('scored');advanceId=setTimeout(()=>{if(session&&!session.paused){$('#mini-ball')?.classList.remove('scored');nextQuestion();}},1000);}
}
function answerError(message){$('#answer-error').textContent=message;$('#answer')?.focus();}
function startTick(){clearInterval(tickId);lastTick=performance.now();tickId=setInterval(()=>{if(!session||session.paused)return;const now=performance.now(),delta=Math.max(0,(now-lastTick)/1000);lastTick=now;session.elapsed+=clockDelta(session,delta);if(session.phase==='question')session.currentMs+=delta*1000;if(session.elapsed>=session.duration){session.elapsed=session.duration;finishMatch(true);return;}updateLive();if(now-lastSave>1100){saveRound();lastSave=now;}},150);}
function updateLive(){if(!session)return;const values={'live-goals':session.correct,'live-streak':session.streak,'live-time':clock(session.duration-session.elapsed)};for(const [id,value]of Object.entries(values)){const el=document.getElementById(id);if(el)el.textContent=value;}if($('#live-xp'))$('#live-xp').innerHTML=`${session.points}<small> XP</small>`;$('#timer-box')?.classList.toggle('low',session.duration-session.elapsed<16&&session.phase==='question');$('#timer-box')?.classList.toggle('clock-rest',session.phase==='feedback');if($('#timer-caption'))$('#timer-caption').textContent=session.phase==='feedback'?'Coach time':'Time';if($('#shot-track'))$('#shot-track').innerHTML=shotTrack();}
function pause(){if(!session)return;clearTimeout(advanceId);session.paused=true;session.pausedEver=true;saveRound();showPauseOverlay();}
function showPauseOverlay(){if($('.paused'))return;$('.game-main').inert=true;$('.game-header').inert=true;const el=document.createElement('div');el.className='paused';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-labelledby','pause-title');el.innerHTML=`<div class="pause-inner">${icon('whistle',58)}<div class="eyebrow" style="justify-content:center;margin-top:20px;color:var(--muted)">TIME OUT</div><h2 id="pause-title">TAKE A BREATHER.</h2><p>${esc(player().name)}’s match is saved.</p><button class="btn lime big" data-action="resume">PLAY ON ${icon('play',18)}</button><button class="btn white" data-action="finish">Finish</button></div>`;app.append(el);requestAnimationFrame(()=>$('[data-action=resume]',el).focus());}
function resume(){session.paused=false;$('.paused')?.remove();$('.game-main').inert=false;$('.game-header').inert=false;if(session.phase==='feedback'&&session.rows.at(-1)?.correct)nextQuestion();else renderQuestion();startTick();saveRound();}
function finishMatch(complete){
 if(!session)return;clearInterval(tickId);clearTimeout(advanceId);window.speechSynthesis?.cancel();
 const p=player(),old=bestFor(session.recordKey),before=new Set(medals(p).filter(x=>x[3]).map(x=>x[0]));
 const saved={...session,complete:complete&&(!session.placement||p.placementComplete),endedAt:Date.now(),elapsed:Math.round(session.elapsed*10)/10};
 for(const key of ['q','selection','retries','seen','answer','digits','notes','drawing','bars','angle','currentMs','lastDigit'])delete saved[key];
 saved.previousBest=old?.points||0;saved.previousTime=old?.elapsed||0;saved.newRecord=newPersonalBest(saved,old);
 if(saved.attempts){p.goalsTotal=totalGoals(p)+saved.correct;p.pointsTotal=clubPoints(p)+saved.points;p.sessions.push(saved);p.sessions=p.sessions.slice(-500);if(saved.mode==='check'&&complete&&saved.probeIndex>=probeIds(p).length)p.placementComplete=true;if(saved.newRecord){p.records||={};p.records[saved.recordKey]={...saved,rows:[]};}saved.medals=medals(p).filter(x=>x[3]&&!before.has(x[0])).map(x=>({name:x[0],symbol:x[2]}));save();}
 session=null;result=saved;saveRound();renderResult();if(saved.newRecord&&!data.settings.reduceMotion)confetti();
}
function renderResult(){const r=result,p=player(),accuracy=r.attempts?Math.round(r.correct/r.attempts*100):0,stars=r.complete&&r.attempts>=5?(accuracy>=95?3:accuracy>=80?2:accuracy>=60?1:0):0,errors=[...new Map(r.rows.filter(x=>!x.correct||x.assisted).map(x=>[x.q.key,x])).values()];
 app.innerHTML=`<div class="game-shell"><header class="game-header">${brand()}<span class="profile-mini">${profileDot(p)}${esc(p.name)}</span><button class="icon-btn" data-action="result-home" aria-label="Go to clubhouse">${icon('home',19)}</button></header><main id="main" class="results"><div class="result-symbol">${icon(r.newRecord?'trophy':'ball',55)}</div><div class="eyebrow">${r.mode==='check'?(r.complete?'WARM-UP COMPLETE':'WARM-UP SAVED'):'MATCH REPORT'}</div><h1>${r.newRecord?'NEW RECORD!':r.complete?'FULL TIME.':'MATCH SAVED.'}</h1><p>${r.mode==='check'?(r.complete?'Coach now has a starting point.':'Your warm-up is saved. Keep going next time.'):r.correct>=8?'Great play, '+esc(p.name)+'.':'Every shot is training.'}</p>${r.newRecord?`<div class="record-banner">${icon('trophy',17)} ${r.points} XP · ${r.previousBest?(r.points===r.previousBest?`${(r.previousTime-r.elapsed).toFixed(1)}s FASTER`:`+${r.points-r.previousBest} ON YOUR BEST`):'FIRST PERSONAL BEST'}</div>`:''}<div class="stars" aria-label="${stars} out of 3 accuracy stars">${[1,2,3].map(n=>`<span class="${n<=stars?'':'off'}">${icon('star',31).replace('fill="none"',n<=stars?'fill="currentColor"':'fill="none"')}</span>`).join('')}</div><div class="result-metrics"><div><strong>${r.correct}/${r.attempts}</strong><small>goals</small></div><div><strong>${r.points}</strong><small>match XP</small></div><div><strong>${accuracy}%</strong><small>accuracy</small></div><div><strong>${r.bestStreak}</strong><small>best streak</small></div></div><div class="level-line" style="max-width:380px;margin:22px auto 0"><strong>LEVEL ${level(p)}</strong><span>${clubPoints(p)%200}/200 XP</span></div><div class="xp" style="max-width:380px;margin:9px auto"><i style="width:${clubPoints(p)%200/2}%"></i></div><div class="result-buttons"><button class="btn lime big" data-action="next-match">${r.mode==='check'?(p.placementComplete?'START TRAINING':'CONTINUE WARM-UP'):'NEXT MATCH'} ${icon('arrow',18)}</button><button class="btn white big" data-action="result-home">Clubhouse</button></div>${goalsMarkup(p,true)}${r.pausedEver||r.hintsUsed?'<p class="muted">Coach helped or match paused. XP counts; this round does not set a timed record.</p>':''}${r.medals?.length?`<section class="panel"><h3>NEW MEDALS</h3><div class="badge-grid">${r.medals.map(m=>`<div class="badge"><span class="badge-icon">${icon(m.symbol,24)}</span><b>${esc(m.name)}</b></div>`).join('')}</div></section>`:''}${errors.length?`<section class="panel"><h3>BACK ON THE TRAINING GROUND</h3><div class="result-review">${errors.slice(0,5).map(x=>`<button data-action="review-example" data-key="${esc(x.q.key)}"><span>${mathText(equationLabel(x.q,false))}</span><span>${icon('whistle',18)}</span></button>`).join('')}</div></section>`:''}<section class="panel"><h3>${r.mode==='check'?'COACH’S NEXT MOVE':'KEEP YOUR MATCH FITNESS'}</h3><p>${r.mode==='check'?'Your next round targets gaps in the warm-up. Facts you know return later.':'Mistakes get a replay. Other facts return on later days.'}</p><button class="text-btn" data-action="how" style="margin-top:10px">How Coach picks ${icon('arrow',13)}</button></section></main></div>`;scrollTo({top:0});}
function sound(good){if(!data.settings.sound)return;try{audio||=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.setValueAtTime(good?600:300,audio.currentTime);o.frequency.linearRampToValueAtTime(good?820:340,audio.currentTime+.12);g.gain.setValueAtTime(.03,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.22);o.start();o.stop(audio.currentTime+.24);}catch{}}
function confetti(){const e=document.createElement('div');e.className='confetti';e.setAttribute('aria-hidden','true');e.innerHTML=Array.from({length:32},(_,i)=>`<i style="left:${Math.random()*100}%;background:${['#d4f36a','#739e5e','#d6b76b','#7a9bdc'][i%4]};animation-delay:${Math.random()*.4}s;--drift:${Math.random()*180-90}px"></i>`).join('');document.body.append(e);setTimeout(()=>e.remove(),2700);}
function speak(text){if(!('speechSynthesis'in window)){toast('Read-aloud is not available in this browser.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(String(text).replace(/×/g,' times ').replace(/÷/g,' divided by ').replace(/−/g,' minus ').replace(/=/g,' equals ').replace(/□/g,' missing number ').replace(/<[^>]*>/g,' '));utterance.lang='en-GB';utterance.rate=.87;speechSynthesis.speak(utterance);}

function openDialog(content,{wide=false,focus=null}={}){returnFocus=document.activeElement;modalRoot.innerHTML=`<div class="dialog-backdrop"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><button class="icon-btn close-dialog" data-action="close-dialog" aria-label="Close">${icon('close',17)}</button>${content}</section></div>`;app.inert=true;requestAnimationFrame(()=>$(focus||'.dialog button,.dialog input,.dialog select,.dialog',modalRoot)?.focus());}
function closeDialog(){if(!modalRoot.firstChild)return;modalRoot.innerHTML='';app.inert=false;if(returnFocus?.isConnected)returnFocus.focus();}
function profileForm(id=null){const p=data.profiles.find(x=>x.id===id);openDialog(`<div class="eyebrow" style="color:var(--muted);margin-bottom:10px">JOIN THE SQUAD</div><h2 id="dialog-title">${p?'Edit player':'New player'}</h2><form id="profile-form" data-id="${p?.id||''}"><div class="field-row"><label for="player-name">Name or nickname</label><input class="field" id="player-name" maxlength="24" required autocomplete="off" value="${esc(p?.name||'')}"></div><div class="field-row"><label for="player-year">School year</label><select class="field" id="player-year"><option value="3" ${!p||p.year===3?'selected':''}>Year 3</option><option value="5" ${p?.year===5?'selected':''}>Year 5</option><option value="0" ${p?.year===0?'selected':''}>My own pace</option></select></div><div class="field-row"><label for="training-clock">Auto training clock</label><select class="field" id="training-clock"><option value="120" ${!p||!p.trainingSeconds||p.trainingSeconds===120?'selected':''}>Match pace · 2 minutes</option><option value="180" ${p?.trainingSeconds===180?'selected':''}>Steady pace · 3 minutes</option><option value="60" ${p?.trainingSeconds===60?'selected':''}>Sprint pace · 1 minute</option></select></div><div class="field-error" id="profile-error" role="alert"></div><div class="dialog-actions">${p&&data.profiles.length>1?`<button type="button" class="text-btn text-danger" data-action="delete-player" data-id="${p.id}" style="margin-right:auto">Delete player</button>`:''}<button class="btn" type="submit">${p?'Save':'LET’S PLAY'} ${icon('arrow',16)}</button></div></form>`,{focus:'#player-name'});}
function showHow(){const plan=planSummary(player());openDialog(`<div class="eyebrow" style="color:var(--muted);margin-bottom:10px">YOUR TRAINING PLAN</div><h2 id="dialog-title">Coach picks the next shot.</h2><div class="records">${plan.map((x,i)=>`<div class="record"><span class="domain-number">${i+1}</span><div><b>${esc(shortTitle(skillById(x.id)))}</b><small>${esc(x.why)}</small></div></div>`).join('')}</div><div class="coach-note">Mistakes get another try after other questions. Two difficult answers trigger a supporting skill. Due facts return on later days. Passing a round is not the same as lasting mastery.</div><div class="dialog-actions"><button class="btn" data-action="close-dialog">Got it ${icon('check',16)}</button></div>`);}
function showReport(id){const p=data.profiles.find(x=>x.id===id),sum=profileSummary(p),plan=planSummary(p);const ids=[...new Set([...plan.map(x=>x.id),...Object.keys(p.learning)])];openDialog(`<div class="eyebrow" style="color:var(--muted);margin-bottom:10px">COACH REPORT</div><h2 id="dialog-title">${esc(p.name)} · Year ${p.year||'open'}</h2><p>${sum.factsSeen} facts seen · ${sum.factsSecure} secure · ${p.sessions.length} matches</p><div class="report-wrap"><table class="report"><thead><tr><th>Skill</th><th>Attempts</th><th>Recent independent accuracy</th><th>Progress</th></tr></thead><tbody>${ids.map(id=>{const c=competency(p,id);return `<tr><td>${esc(shortTitle(skillById(id)))}</td><td>${c.n}</td><td>${c.accuracy===null?'Not yet':c.accuracy+'%'}</td><td>${c.secure?'Match fit':c.ready?'Ready to build on':c.n?'Needs practice':'Not yet sampled'}</td></tr>`;}).join('')}</tbody></table></div><h3 style="font-size:16px;margin-top:24px">Why those questions?</h3><div class="report-wrap"><table class="report"><thead><tr><th>Question</th><th>Result</th><th>Selection reason</th></tr></thead><tbody>${p.sessions.slice(-2).flatMap(s=>s.rows||[]).slice(-12).map(r=>`<tr><td>${esc(equationLabel(r.q,false))}</td><td>${r.correct&&!r.assisted?'Independent':r.assisted?'Supported':'Mistake'}</td><td>${esc(r.detail||'Earlier practice')}</td></tr>`).join('')}</tbody></table></div><div class="coach-note">“Ready to build on” uses recent independent answers to allow progression. “Match fit” requires spaced success and coverage. The report shows sampled performance, rather than a diagnosis.</div><div class="dialog-actions"><button class="btn white" data-action="export-csv" data-id="${p.id}">Export scores</button><button class="btn" data-action="close-dialog">Done</button></div>`,{wide:true});}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1200);}
function csv(p){const rows=[['Player','Date','Match','Goals','Shots','XP','Seconds','Complete','Hints','Paused'],...p.sessions.map(s=>[p.name,new Date(s.endedAt).toISOString(),s.mode==='check'?'Warm-up':recordLabel(s),s.correct,s.attempts,s.points,s.elapsed,s.complete,s.hintsUsed,s.pausedEver])];return rows.map(row=>row.map(v=>{let s=String(v);if(/^[=+@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
function restoreFile(file){if(file.size>20*1024*1024){toast('Choose a backup under 20 MB.');return;}file.text().then(text=>{pendingImport=validateImport(JSON.parse(text));for(const p of pendingImport.profiles)initLearning(p);openDialog(`<h2 id="dialog-title">Restore ${pendingImport.profiles.length} players?</h2><p>This replaces the squad and results currently saved in this browser. Download a backup first if you want to keep them.</p><div class="dialog-actions"><button class="btn white" data-action="close-dialog">Cancel</button><button class="btn" data-action="confirm-import">Restore squad</button></div>`);}).catch(err=>toast(err.message||'Could not read that backup.'));}
function pressKeypad(key){if(!session||session.paused||session.phase!=='question')return;if(session.q.key.startsWith('column')){const ins=$$('.column-digit');let i=session.lastDigit??ins.length-1;if(key==='clear'){ins.forEach(e=>e.value='');i=ins.length-1;}else if(key==='back'){if(ins[i].value)ins[i].value='';else{i=Math.min(ins.length-1,i+1);ins[i].value='';}}else if(/^\d$/.test(key)){ins[i].value=key;i=Math.max(0,i-1);}session.lastDigit=i;session.digits=ins.map(e=>e.value);ins[i].focus();}else{const el=$('#answer')||$$('.bar-input')[session.lastBar??0];if(!el)return;el.value=key==='clear'?'':key==='back'?el.value.slice(0,-1):(el.value+key).slice(0,24);if(el.id==='answer')session.answer=el.value;else{session.bars[Number(el.dataset.bar)]=el.value;const bar=$(`#bar-view-${el.dataset.bar}`);if(bar)bar.style.height=`${Math.min(20,Math.max(0,Number(el.value)))*5}px`;}el.focus();}saveRound();}
function handleClick(event){const b=event.target.closest('[data-action]');if(!b||b.disabled)return;event.preventDefault();switch(b.dataset.action){
 case 'home':if(session)pause();else navigate('home');break;
 case 'nav':navigate(b.dataset.view);break;
 case 'players':if(!session){pendingSkill=null;result=null;data.activeId=null;save();view='players';location.hash='players';render();scrollTo({top:0});}break;
 case 'choose-player':data.activeId=b.dataset.id;year=player().year>=5?5:3;save();startMatch(pendingSkill);pendingSkill=null;break;
 case 'new-player':profileForm();break;
 case 'edit-player':profileForm(b.dataset.id);break;
 case 'delete-player':{const p=data.profiles.find(x=>x.id===b.dataset.id);openDialog(`<h2 id="dialog-title">Delete ${esc(p.name)}?</h2><p>This removes this player’s progress from this browser. Back up first if you want to keep it.</p><div class="dialog-actions"><button class="btn white" data-action="close-dialog">Keep player</button><button class="btn danger" data-action="confirm-delete" data-id="${p.id}">Delete player</button></div>`);break;}
 case 'confirm-delete':data.profiles=data.profiles.filter(p=>p.id!==b.dataset.id);if(data.activeId===b.dataset.id)data.activeId=data.profiles[0].id;save();closeDialog();render();toast('Player removed.');break;
 case 'browse':year=data.activeId&&player().year>=5?5:3;navigate('syllabus');break;
 case 'play':startMatch();break;
 case 'skill':if(!data.activeId){pendingSkill=b.dataset.skill;view='players';render();scrollTo({top:0});}else startMatch(b.dataset.skill);break;
 case 'year':year=Number(b.dataset.year);render();break;
 case 'domain':domain=b.dataset.domain;render();break;
 case 'table-map':tableView=Number(b.dataset.table);$('#table-tracker-host')?$('#table-tracker-host').innerHTML=factMapMarkup(player(),tableView):render();break;
 case 'sound':data.settings.sound=!data.settings.sound;save();sound(true);if(!session&&!result)render();else toast(`Sound ${data.settings.sound?'on':'off'}`);break;
 case 'hear':if(session)speak(`${questionPrompt(session.q)}. ${session.q.expression!==undefined?session.q.expression:coreExpression(session.q)}`);break;
 case 'hear-help':if(session)speak((session.q.hint||explain(session.q).steps).join('. '));else if(modalRoot.dataset.question)speak(modalRoot.dataset.question);break;
 case 'hint':if(session&&!session.assisted){session.assisted=true;session.hintsUsed++;saveRound();renderQuestion();}break;
 case 'answer-choice':submit(b.dataset.value);break;
 case 'next':if(session&&!session.paused)nextQuestion();break;
 case 'key':pressKeypad(b.dataset.key);break;
 case 'draw-point':if(session&&session.phase==='question'){const point=[Number(b.dataset.x),Number(b.dataset.y)],idx=session.drawing.findIndex(p=>p[0]===point[0]&&p[1]===point[1]);if(idx>=0)session.drawing.splice(idx,1);else if(session.drawing.length<session.q.visual.sides)session.drawing.push(point);saveRound();renderQuestion();}break;
 case 'draw-undo':if(session){session.drawing.pop();renderQuestion();saveRound();}break;
 case 'draw-clear':if(session){session.drawing=[];renderQuestion();saveRound();}break;
 case 'pause':pause();break;
 case 'resume':resume();break;
 case 'finish':finishMatch(false);break;
 case 'result-home':result=null;navigate('home');break;
 case 'next-match':{const manual=result?.manual||null;startMatch(manual);break;}
 case 'review-example':{const q=result.rows.find(r=>r.q.key===b.dataset.key).q;modalRoot.dataset.question=(q.hint||explain(q).steps).join('. ');openDialog(`<h2 id="dialog-title">COACH’S REPLAY</h2><div class="q-prompt" style="margin-top:25px">${esc(questionPrompt(q))}</div><div class="q-equation compact">${mathText(equationLabel(q,true))}</div>${q.visual?diagram(q.visual):''}${helpMarkup(q)}<div class="dialog-actions"><button class="btn" data-action="close-dialog">Got it ${icon('check',15)}</button></div>`);break;}
 case 'how':showHow();break;
 case 'report':showReport(b.dataset.id);break;
 case 'close-dialog':closeDialog();break;
 case 'backup':download(JSON.stringify({...data,exportedAt:new Date().toISOString()},null,2),`Matchday_Maths_Backup_${localDay()}.json`,'application/json');toast('Backup downloaded.');break;
 case 'import':$('#import-file').click();break;
 case 'confirm-import':data=validateImport(pendingImport);for(const p of data.profiles)initLearning(p);pendingImport=null;session=null;saveRound();save();closeDialog();view='coach';render();toast('Squad restored.');break;
 case 'export-csv':{const p=b.dataset.id?data.profiles.find(x=>x.id===b.dataset.id):player();download(csv(p),`Matchday_${p.name.replace(/[^a-z0-9]/gi,'_')}_Scores.csv`,'text/csv;charset=utf-8');break;}
 }}
 document.addEventListener('click',handleClick);
 document.addEventListener('submit',event=>{if(event.target.id==='answer-form'){event.preventDefault();submit();}if(event.target.id==='profile-form'){event.preventDefault();const id=event.target.dataset.id,name=$('#player-name').value.trim(),y=Number($('#player-year').value);if(!name)return $('#profile-error').textContent='Add a name.';if(data.profiles.some(p=>p.id!==id&&p.name.toLowerCase()===name.toLowerCase()))return $('#profile-error').textContent='That player already exists. Add an initial.';if(id){const p=data.profiles.find(p=>p.id===id);if(p.year!==y){p.placementComplete=false;p.placementProgress=0;}p.name=name;p.year=y;p.trainingSeconds=Number($('#training-clock').value);save();closeDialog();render();}else{const p=newProfile(name,y,['sprout','flower','tree'][data.profiles.length%3]);initLearning(p);p.trainingSeconds=Number($('#training-clock').value);data.profiles.push(p);data.activeId=p.id;save();closeDialog();startMatch(pendingSkill);pendingSkill=null;}}});
 document.addEventListener('input',event=>{const el=event.target;if(el.id==='answer'&&session){el.value=el.value.replace(/[^0-9.,/\s−-]/g,'').slice(0,24);session.answer=el.value;saveRound();}if(el.classList?.contains('column-digit')&&session){el.value=el.value.replace(/\D/g,'').slice(-1);session.digits=$$('.column-digit').map(x=>x.value);if(el.value){const next=$(`#digit-${Number(el.dataset.digit)-1}`);if(next){session.lastDigit=Number(next.dataset.digit);next.focus();next.select();}}saveRound();}if(el.classList?.contains('column-note')&&session){session.notes[Number(el.dataset.note)]=el.value.replace(/\D/g,'').slice(0,2);saveRound();}if(el.classList?.contains('bar-input')&&session){session.bars[Number(el.dataset.bar)]=el.value;const bar=$(`#bar-view-${el.dataset.bar}`);if(bar)bar.style.height=`${Math.min(20,Math.max(0,Number(el.value)))*5}px`;saveRound();}if(el.id==='angle-control'&&session){session.angle=Number(el.value);const current=$('.math-visual',$('#question-host'));if(current){const holder=document.createElement('div');holder.innerHTML=diagram(session.q.visual,{angle:session.angle});current.replaceWith(holder.firstElementChild);}saveRound();}if(el.id==='skill-search'){search=el.value;$('#syllabus-bank').innerHTML=syllabusBank();}});
 document.addEventListener('focusin',event=>{if(event.target.classList?.contains('bar-input')&&session)session.lastBar=Number(event.target.dataset.bar);if(event.target.classList?.contains('column-digit')&&session){session.lastDigit=Number(event.target.dataset.digit);event.target.select();}});
 document.addEventListener('change',event=>{if(event.target.id==='reduce-motion'){data.settings.reduceMotion=event.target.checked;document.body.classList.toggle('reduce-motion',event.target.checked);save();}if(event.target.id==='import-file'){const file=event.target.files?.[0];if(file)restoreFile(file);event.target.value='';}});
 document.addEventListener('keydown',event=>{const container=modalRoot.firstChild?modalRoot:session?.paused?$('.paused'):null;if(container){if(event.key==='Escape'&&container===modalRoot){event.preventDefault();closeDialog();return;}if(event.key==='Tab'){const controls=$$('button:not([disabled]),input:not([hidden]):not([disabled]),select,a[href],[tabindex="0"]',container).filter(e=>e.offsetParent!==null);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}return;}if(session&&!session.paused){if(event.key==='Escape'){event.preventDefault();pause();return;}if(event.key==='Enter'&&session.phase==='feedback'){event.preventDefault();nextQuestion();}if(event.target.classList?.contains('column-digit')){const i=Number(event.target.dataset.digit);if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();$(`#digit-${i+(event.key==='ArrowLeft'?-1:1)}`)?.focus();}if(event.key==='Backspace'&&event.target.value===''){event.preventDefault();$(`#digit-${i+1}`)?.focus();}}}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&session&&!session.paused)pause();});
 window.addEventListener('pagehide',()=>{if(session){session.paused=true;session.pausedEver=true;saveRound();}save();});
 year=player().year>=5?5:3;render();if(session)startTick();
